</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define INF 17446744073709551616ULL
#define ULL unsigned long long
using namespace std;

ULL mod, n, k, dp[19][300005];
ULL fac[300005], inv[300005];

ULL qpow(ULL a, ULL b) {
    ULL res = 1ULL, base = a;
    while (b) {
        if (b & 1ULL) {
            res *= base;
            res %= mod;
        }
        base *= base;
        base %= mod;
        b >>= 1ULL;
    }
    return res;
}

ULL combination(int a, int b) {
    return (((fac[a] * inv[b]) % mod) * inv[a - b]) % mod;
}

ULL compute() {
    int i, j, l;
    fac[0] = 1ULL;
    ULL limit = max(n, k);
    for (i = 1; i <= limit; i++) {
        fac[i] = (fac[i - 1] * (ULL)(i)) % mod;
    }
    inv[limit] = qpow(fac[limit], mod - 2ULL);
    for (i = limit - 1; i >= 0; i--) {
        inv[i] = (inv[i + 1] * (ULL)(i + 1)) % mod;
    }
    for (i = 1; i <= n; i++) {
        dp[1][i] = inv[i];
    }
    ULL answer = dp[1][n] * combination(k, 1) % mod;
    int t = min(18, (int)k);
    for (i = 2; i <= t; i++) {
        for (j = n; j; j = (j - 1) & n) {
            if (!dp[i - 1][j]) continue;
            int r = n ^ j;
            for (l = r; l > j; l = (l - 1) & r) {
                dp[i][j ^ l] += dp[i - 1][j] * inv[l];
                if (dp[i][j ^ l] > INF) dp[i][j ^ l] %= mod;
            }
        }
        for (j = n; j; j = (j - 1) & n) {
            if (dp[i][j] >= mod) dp[i][j] %= mod;
        }
        ULL res = dp[i][n] * combination(k, i) % mod;
        res = res * fac[i] % mod;
        answer = (answer + res >= mod ? answer + res - mod : answer + res);
    }
    answer = answer * fac[n] % mod;
    return answer;
}

int main() {
    cin >> n >> k >> mod;
    ULL ans = qpow(k, n);
    if (n % 2 == 0) ans = (ans - compute() + mod) % mod;
    cout << ans << endl;
    return 0;
}
